// seed: tests/seed.admin.spec.ts (admin, с #359741; было: гость) · прод, только чтение. Источник: комментарий #8790d6 2026-11-03, «מה רצוי» #d012a3 и #92bc03, D-07;
// обновлено 2026-11-04 по принятым #94553b (шаг «האזור האישי»), #d152dd (шаг «חפש עסק»), #66ad36 (шаги «מועדפים ושיחות», «הוספה למסך הבית»).
import { test, expect } from '@playwright/test';
import { prepareReadOnly, GUIDES, LOAD, openGuides, card, videoOf, stepTexts } from './guides.helpers';

// #359741: /guides видит только админ (гость и user уходят на /) — сессия admin, файл сессии не перезаписывается.
test.use({ storageState: '../auth/admin.json', serviceWorkers: 'block' });

test.describe('Видео-инструкции /guides', () => {
  test('/guides: 5 карточек — заголовки, порядок, длительность, описания, шаги карточек #8790d6 #d012a3 #92bc03 #94553b #d152dd #66ad36 @desktop @prod-safe', async ({ page, context }) => {
    await prepareReadOnly(context);
    await openGuides(page);

    await expect(page, 'админ остаётся на /guides, без редиректа на / или /auth (#359741)').toHaveURL(/\/guides\/?(\?.*)?$/);
    await expect(page.getByRole('heading', { level: 1, name: 'מדריכי וידאו' })).toBeVisible(LOAD);
    await expect(page.getByText('הסרטונים עם קריינות בעברית והסבר כתוב על המסך')).toBeVisible();

    const articles = page.getByRole('article');
    await expect(articles).toHaveCount(5);
    await expect(articles.getByRole('heading', { level: 2 }), 'порядок карточек').toHaveText(GUIDES.map((g) => g.title));

    for (const [i, g] of GUIDES.entries()) {
      const c = card(page, g);
      await expect(c, `карточка ${g.id}`).toBeVisible();
      await expect(c.getByText(`מדריך ${i + 1} · ${g.duration}`, { exact: true }), `${g.id}: метка длительности`).toBeVisible();

      const v = videoOf(page, g);
      await expect(v, `${g.id}: video внутри своей карточки`).toHaveCount(1);
      await expect(c.locator('video')).toHaveAttribute('aria-label', `סרטון: ${g.title}`);
      await expect(v).toHaveAttribute('src', `/guides/${g.id}.mp4`);
      await expect(v).toHaveAttribute('poster', `/guides/${g.id}.jpg`);
      await expect(v).toHaveAttribute('controls', '');

      expect(await stepTexts(c), `${g.id}: шаги — текст, порядок, количество`).toEqual([...g.steps]);
      await expect(c.getByText(g.description, { exact: true }), `${g.id}: описание карточки`).toBeVisible();
    }

    const signup = card(page, GUIDES[1]);
    await expect(signup.getByText('פותחים חשבון עם Google או במספר נייד וקוד SMS, ומתחברים בפעם הבאה מאותו מסך.', { exact: true })).toBeVisible();
    for (const word of ['אימייל', 'סיסמה']) {
      expect((await stepTexts(signup)).filter((s) => s.includes(word)), `signup: нет шага с «${word}»`).toEqual([]);
    }

    await expect(card(page, GUIDES[3]).getByRole('listitem').filter({ hasText: 'סוג מכירה: פרטי / תיווך' })).toHaveCount(1);

    // #94553b: последний шаг home — «האזור האישי» (реджект rej_1c61399f «גם בשלבים»).
    expect((await stepTexts(card(page, GUIDES[0]))).at(-1), 'home: последний шаг').toBe('האזור האישי');
    // #d152dd: шаг «חפש עסק» сразу после «חיפוש חופשי מדף הבית» (реджект rej_6e4e6ad9 п.1).
    expect((await stepTexts(card(page, GUIDES[3])))[1], 'search: шаг 2').toBe('«חפש עסק»: חיפוש וסינון מכל מקום בעמוד');
    // #66ad36: в шагах area есть «מועדפים ושיחות» и «הוספה למסך הבית» (реджект rej_b4d07439).
    expect(await stepTexts(card(page, GUIDES[4])), 'area: шаги покупателя и «מסך הבית»').toEqual(expect.arrayContaining(['מועדפים ושיחות', 'הוספה למסך הבית']));
  });
});
